def frequency_lists(lists):
    flat_list = [num for sublist in lists for num in sublist]
    freq_dict = {}
    for num in flat_list:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1
    return freq_dict

